//! ArchiMate element corner icons.
//!
//! Each ArchiMate element carries a small black corner icon. These are
//! PlantUML's archimate sprite glyphs (from
//! `plantuml/src/main/resources/sprites/archimate/*.svg`), captured as the
//! exact `<path d=...>` PlantUML emits. The icon is anchored to the element
//! box's **top-right corner**: the stored canonical path expresses every X
//! coordinate relative to the box's right edge (`box_x + box_w`) and every Y
//! coordinate relative to the box top (`box_y`). At render time the canonical
//! coordinates are translated onto the element's oracle-supplied box position.
//!
//! Anchoring to the right edge (not the left) reproduces PlantUML's placement
//! for variable-width boxes: wider boxes (`RoundCorner 25` elements with long
//! labels, e.g. WorkPackage) keep the icon flush to the right margin.

use crate::plantuml_metrics as pm;

/// Look up the canonical icon path for a `{Layer}_{Kind}` key. Returns the
/// path with X coordinates relative to the box right edge and Y relative to the
/// box top; translate with [`translate`]. `None` when no icon is known.
pub fn icon_path(key: &str) -> Option<&'static str> {
    let p = match key {
        "Application_Component" => APPLICATION_COMPONENT,
        "Application_Service" => APPLICATION_SERVICE,
        "Business_Actor" => BUSINESS_ACTOR,
        "Business_Function" => BUSINESS_FUNCTION,
        "Business_Process" => BUSINESS_PROCESS,
        "Business_Role" => BUSINESS_ROLE,
        "Implementation_Deliverable" => IMPLEMENTATION_DELIVERABLE,
        "Implementation_Gap" => IMPLEMENTATION_GAP,
        "Implementation_Plateau" => IMPLEMENTATION_PLATEAU,
        "Implementation_WorkPackage" => IMPLEMENTATION_WORKPACKAGE,
        "Motivation_Assessment" => MOTIVATION_ASSESSMENT,
        "Motivation_Constraint" => MOTIVATION_CONSTRAINT,
        "Motivation_Driver" => MOTIVATION_DRIVER,
        "Motivation_Goal" => MOTIVATION_GOAL,
        "Motivation_Principle" => MOTIVATION_PRINCIPLE,
        "Motivation_Requirement" => MOTIVATION_REQUIREMENT,
        "Motivation_Stakeholder" => MOTIVATION_STAKEHOLDER,
        "Technology_Artifact" => TECHNOLOGY_ARTIFACT,
        "Technology_CommunicationNetwork" => TECHNOLOGY_COMMUNICATIONNETWORK,
        "Technology_Node" => TECHNOLOGY_NODE,
        "Technology_SystemSoftware" => TECHNOLOGY_SYSTEMSOFTWARE,
        _ => return None,
    };
    Some(p)
}

/// Translate a canonical icon path onto a box anchored at right edge `x_anchor`
/// (`box_x + box_w`) and top `y_anchor` (`box_y`). Coordinates are emitted with
/// PlantUML's coordinate formatting. Recognises the absolute path commands that
/// appear in archimate icons (`M`, `L`, `C`, `Q`, `A`, `H`, `V`); for an arc
/// `A rx ry rot laf sf x y` only the final `x,y` are translated.
pub fn translate(d: &str, x_anchor: f64, y_anchor: f64) -> String {
    let mut out = String::with_capacity(d.len() + 16);
    let bytes = d.as_bytes();
    let mut i = 0;
    let mut cmd = b' ';
    let mut argi = 0usize;
    while i < bytes.len() {
        let b = bytes[i];
        if b.is_ascii_alphabetic() {
            cmd = b;
            argi = 0;
            out.push(b as char);
            i += 1;
            continue;
        }
        if b == b'-' || b == b'.' || b.is_ascii_digit() {
            let start = i;
            if bytes[i] == b'-' {
                i += 1;
            }
            while i < bytes.len()
                && (bytes[i].is_ascii_digit()
                    || bytes[i] == b'.'
                    || bytes[i] == b'e'
                    || bytes[i] == b'E'
                    || ((bytes[i] == b'-' || bytes[i] == b'+')
                        && i > start
                        && (bytes[i - 1] == b'e' || bytes[i - 1] == b'E')))
            {
                i += 1;
            }
            let num: f64 = d[start..i].parse().unwrap_or(0.0);
            match arg_role(cmd, argi) {
                Role::X => out.push_str(&pm::fmt_coord(num + x_anchor)),
                Role::Y => out.push_str(&pm::fmt_coord(num + y_anchor)),
                Role::Other => out.push_str(&d[start..i]),
            }
            argi += 1;
            continue;
        }
        out.push(b as char);
        i += 1;
    }
    out
}

enum Role {
    X,
    Y,
    Other,
}

/// Classify a path argument by its command and zero-based argument index.
fn arg_role(cmd: u8, argi: usize) -> Role {
    match cmd {
        b'M' | b'L' | b'T' | b'C' | b'S' | b'Q' => {
            if argi.is_multiple_of(2) {
                Role::X
            } else {
                Role::Y
            }
        }
        b'A' => match argi % 7 {
            5 => Role::X,
            6 => Role::Y,
            _ => Role::Other,
        },
        b'H' => Role::X,
        b'V' => Role::Y,
        _ => Role::Other,
    }
}

